  if(bd<boss.r+player.r+10&&player.inv<=0){hitPlayer(16)} }
 for(let i=projectiles.length-1;i>=0;i--){let p=projectiles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(dist(p,player)<p.r+player.r&&player.inv<=0){hitPlayer(12);projectiles.splice(i,1)}else if(p.life<0)projectiles.splice(i,1)}
 slashes.forEach(s=>s.life-=dt);slashes=slashes.filter(s=>s.life>0);camera.x+=(player.x-camera.x)*.09;camera.y+=(player.y-camera.y)*.09;camera.shake*=.82;
 document.getElementById('bossHp').style.width=(boss.hp/boss.maxHp*100)+'%';document.getElementById('health').style.width=(player.hp/player.maxHp*100)+'%';document.getElementById('hpText').textContent=Math.ceil(player.hp)+' / '+player.maxHp;document.querySelector('.stamina').style.width=player.stamina+'%';document.getElementById('potion').textContent=player.potions;}
function hitPlayer(n){if(!playing)return;player.hp-=n;player.inv=.7;camera.shake=12;document.getElementById('hitFlash').style.opacity=1;setTimeout(()=>document.getElementById('hitFlash').style.opacity=0,100);if(player.hp<=0){player.hp=0;playing=false;setTimeout(()=>end(false),500)}}
