 // ground
 x.fillStyle='#26392b';x.fillRect(camera.x-W/2-100,camera.y-H/2-100,W+200,H+200);x.fillStyle='#314631';for(let i=-3;i<8;i++){for(let j=-3;j<8;j++){let gx=Math.floor((camera.x-W/2)/260)*260+i*260,gy=Math.floor((camera.y-H/2)/260)*260+j*260;x.beginPath();x.ellipse(gx+rnd(-20,20),gy+rnd(-20,20),rnd(40,90),rnd(25,70),rnd(0,6),0,Math.PI*2);x.fill()}}
