#start,#gameover{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at 50% 40%,rgba(43,66,49,.25),rgba(5,8,7,.88));text-align:center;color:#eee8d3}.panel{width:min(580px,88vw);padding:34px;border:1px solid rgba(220,205,159,.35);background:rgba(12,18,14,.86);box-shadow:0 20px 80px #000}.kicker{font-size:11px;letter-spacing:7px;color:#b8a66d;text-transform:uppercase}h1{font-size:54px;margin:12px 0 4px;font-weight:normal;letter-spacing:3px}h1 em{display:block;font-size:15px;letter-spacing:8px;color:#cf9b55;margin-top:8px}.panel p{color:#bab49f;line-height:1.7;font-size:14px}button{pointer-events:auto;margin-top:18px;border:1px solid #beaa70;background:#ae9149;color:#17140d;padding:12px 30px;font:14px Georgia;letter-spacing:3px;text-transform:uppercase;cursor:pointer}button:hover{background:#d2b963}.controls{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:18px;font:11px monospace;color:#d8d2b9}.key{color:#e8c66f}#gameover{display:none}.hidden{display:none!important}
.damage{position:absolute;color:#fff1bb;font:bold 19px monospace;text-shadow:1px 2px 2px #000;transform:translate(-50%,-50%);animation:float .8s forwards}@keyframes float{to{transform:translate(-50%,-90px);opacity:0}}
#vignette{position:absolute;inset:0;box-shadow:inset 0 0 120px rgba(0,0,0,.75);pointer-events:none}#hitFlash{position:absolute;inset:0;background:rgba(180,25,18,.18);opacity:0;transition:.12s}
